    'verdict': 'fail',
    'findings': [
      {'severity': 'major', 'file': 'src/greeting.js', 'line': 2, 'summary': 'The changed public behavior has no automated test in the supplied diff.', 'evidence': 'Product Spec line 9 requires greeting() to return exactly \"after\". Default review rules line 7 require behavioral correctness to be demonstrated with an automated test.'},
      {'severity': 'major', 'file': 'src/greeting.js', 'line': 2, 'summary': 'The patch hard-codes \"after\" although src/message.js:1 defines GREETING_MESSAGE with the same value.', 'evidence': 'Default review rules line 9 require knowledge and logic duplication to be removed.'}
